  return d3.range(controls.n).map(rand);
}
xbar = d3.mean(X)

// ========= Helpers =========
makeDensityReducer = (total) =&gt; (values, extent) =&gt;
  values.length / Math.max(1, total) / Math.max(1e-9, extent.x2 - extent.x1);

// ========= Left panel: current sample (histogram + dots at y=0) =========
leftDensity = makeDensityReducer(controls.n)
xExtent = d3.extent(X)
xPad = 3 * controls.trueSigma
xDomain = [xExtent[0] - 0.1 * (xPad || 1), xExtent[1] + 0.1 * (xPad || 1)]

// === Compute yMax from actual binned densities ===
bins = d3.bin().domain(xDomain).thresholds(controls.bins)(X);
densities = bins.map(b =&gt;
  (b.length / Math.max(1, controls.n)) / Math.max(1e-9, (b.x1 - b.x0))
);
yMax = d3.max(densities);
stickHeight = 0.1 * yMax; // 10% of the current y-range used by the histogram

leftPlot = Plot.plot({
  width: Math.min(600, Math.max(320, width/2 - 20)),
  height: 320,
  style: {
    background: "var(--plot-panel-bg)",
    color: "var(--brand-fg)"           // drives 'currentColor'
  },
  x: { label: "Data", domain: xDomain },
  y: { label: "Density" },
  marks: [
    // histogram
    Plot.rectY(
      X,
      Plot.binX(
        { y: leftDensity },
        {
          x: d =&gt; d,
          thresholds: controls.bins,
          inset: 0,
          fillOpacity: 0.4,
          fill: "var(--brand-teal)"
        }
      )
    ),
    // raw points
    // Plot.dot(
    //   X.map(x =&gt; ({ x, y: 0 })),
    //   {
    //     x: "x",
    //     y: "y",
    //     r: 2,
    //     fillOpacity: 0.9,
    //     fill: "var(--brand-teal)",
    //     symbol: "cross"
    //   }
    // ),
    Plot.ruleX(
    X,
    { y1: 0, y2: yMax * 0.05, stroke: "var(--brand-teal)", strokeWidth: 3, strokeOpacity: 1.}
    ),
    // xbar reference
    Plot.ruleX([xbar], { stroke: "currentColor", strokeDasharray: "4,3" }),
    Plot.dot([{ x: xbar, y: 0 }], { x: "x", y: "y", r: 3, fill: "currentColor" }),
    Plot.ruleY([0])
  ]
})

// ========= Right panel: saved sample means (strip + hist + optional true curve) =========
means = meanHistory
rightDensity = makeDensityReducer(means.length)

mPad = 3 * controls.trueSigma / Math.sqrt(controls.n)
meansDomain = means.length ? d3.extent(means) : [controls.trueMu - mPad, controls.trueMu + mPad]
mDomain = [
  Math.min(meansDomain[0], controls.trueMu - mPad),
  Math.max(meansDomain[1], controls.trueMu + mPad)
]

sampleMeanPdf = (x) =&gt;
  (1 / Math.sqrt(2 * Math.PI * (controls.trueSigma**2 / controls.n))) *
  Math.exp(-((x - controls.trueMu)**2) / (2 * (controls.trueSigma**2 / controls.n)))

pdfXs = d3.scaleLinear().domain(mDomain).ticks(200)
pdfData = pdfXs.map(x =&gt; ({ x, y: sampleMeanPdf(x) }))

rightPlot = Plot.plot({
  width: Math.min(600, Math.max(320, width/2 - 20)),
  height: 320,
  style: {                     // make the figure match your theme
    background: "var(--plot-panel-bg)",
    color: "var(--brand-fg)"   // this drives 'currentColor'
  },
  x: { label: "x̄", domain: mDomain },
  y: { label: "Density" },
  marks: [
    Plot.rectY(
      means,
      Plot.binX(
        { y: rightDensity },
        { x: d =&gt; d, thresholds: controls.bins, inset: 0, fillOpacity: 0.3,
          fill: "var(--brand-red)" }
      )
    ),
    Plot.dot(means.map(m =&gt; ({ x: m, y: 0 })), {
      x: "x", y: "y", r: 2, fillOpacity: 0.7, fill: "var(--brand-red)"
    }),
    Plot.dot([{ x: xbar, y: 0 }], {
      x: "x", y: "y", r: 4, fill: "currentColor"     // uses style.color above
    }),
    ...(controls.showTrue
      ? [Plot.line(pdfData, { x: "x", y: "y", strokeWidth: 2, stroke: "var(--brand-red)" })]
      : []
    ),
    Plot.ruleY([0])
  ]
})

