viewof controls = {

  // Left column: data & truth
  const leftForm = Inputs.form({
    n: Inputs.range([1, 400], { value: 10, step: 1, label: md`${tex`n`}` }),
    trueMu: Inputs.range([-2, 2], { value: 0, step: 0.1, label: md`${tex`\mu_{\text{true}}`}` }),
    trueSigma: Inputs.range([0.3, 3], { value: 1, step: 0.1, label: md`${tex`\sigma_{\text{true}}`}` })
  }, { submit: false });

  // Right column: display & actions
  const rightForm = Inputs.form({
    bins: Inputs.range([10, 60], { value: 24, step: 1, label: "Histogram bins" }),
    showTrue: Inputs.toggle({ label: md`Show ${tex`\bar{X}`} distribution`, value: false }),
    // include the buttons as inputs so their *click counts* become part of form.value
  }, { submit: false });

  // Collapsible wrapper
  const root = html`&lt;details class="controls-root" open&gt;
    &lt;summary&gt;Simulation controls&lt;/summary&gt;
    &lt;div class="controls-grid"&gt;
      &lt;div class="controls-col"&gt;&lt;h4&gt;Data & truth&lt;/h4&gt;&lt;/div&gt;
      &lt;div class="controls-col"&gt;&lt;h4&gt;Display & actions&lt;/h4&gt;&lt;/div&gt;
    &lt;/div&gt;
  &lt;/details&gt;`;
  root.querySelector(".controls-grid").children[0].append(leftForm);
  root.querySelector(".controls-grid").children[1].append(rightForm);

  // Merge both forms into a single value object
  const getValue = () =&gt; ({ ...leftForm.value, ...rightForm.value });
  const update = () =&gt; {
    root.value = getValue();
    root.dispatchEvent(new CustomEvent("input", { bubbles: true }));
  };

  leftForm.addEventListener("input", update);
  rightForm.addEventListener("input", update);
  // make sure button clicks trigger updates even if no 'input' is fired

  queueMicrotask(update);
  return root;
}
